import { update } from './app/store.js';
import { FLIP_UNIT, sacrificeQuote } from './app/sacrifices.js';
import { __setSacrificePanelDepsForTest } from './components/app-sacrifice-panel.js';

const wallet = '0x1111111111111111111111111111111111111111';
let snapshot;
let state = 'ready';
__setSacrificePanelDepsForTest({
  read: async () => state === 'offline' ? null : structuredClone(snapshot),
  sacrifice: async ({ deityKey, amount, onSubmitted }) => {
    onSubmitted?.();
    await new Promise((resolve) => setTimeout(resolve, 700));
    const pool = snapshot.pools.find((item) => item.key === deityKey);
    const quote = sacrificeQuote(amount, snapshot.multiplierUnits, pool.totalWeight);
    pool.totalDonatedWei += amount;
    pool.totalWeight += quote.weight;
    pool.entryCount += 1;
    snapshot.balanceWei -= amount;
    return { awardDay: snapshot.awardDay };
  },
});

function reset() {
  document.querySelector('#sacrifice-demo-host').replaceChildren();
  state = document.querySelector('#sacrifice-demo-state').value;
  update('connected.address', state === 'disconnected' ? null : wallet);
  update('ui.chainOk', true);
  update('ui.mode', 'self');
  snapshot = {
    day: 142, awardDay: 143, menuReady: state !== 'waiting', ended: state === 'ended',
    balanceWei: state === 'disconnected' ? null : (state === 'poor' ? 80n : 18420n) * FLIP_UNIT,
    multiplierUnits: state === 'disconnected' ? null : 1600, score: 400,
    pools: [
      { key: 'vault', totalDonatedWei: 12400n * FLIP_UNIT, totalWeight: 148800n, entryCount: 18, awardedMask: 0, slots: [3, 9, 6] },
      { key: 'sdgnrs', totalDonatedWei: 8300n * FLIP_UNIT, totalWeight: 99600n, entryCount: 11, awardedMask: 0, slots: [40, 24, 43] },
    ],
  };
  if (state === 'empty') snapshot.pools.forEach((pool) => { pool.totalDonatedWei = 0n; pool.totalWeight = 0n; pool.entryCount = 0; });
  document.querySelector('#sacrifice-demo-host').append(document.createElement('app-sacrifice-panel'));
}
document.querySelector('#sacrifice-demo-state').addEventListener('change', reset);
reset();
